//! `devd` client (issue #497): the device manager's view of every device.
//!
//! The `os.lazy.devd.v1` stubs are generated by `midlc` from `idl/devd.midl`;
//! this module adds the reply framing and the blocking [`Client`] alias.

use alloc::vec::Vec;

use libmessenger::{Header, Parcel, VERSION};

use super::client::Native;

/// The generated `os.lazy.devd.v1` stubs.
pub use messenger_generated::os_lazy_devd_v1 as wire;

/// One device as `devd` reports it.
pub use wire::DeviceState;

/// Registered service name.
pub const NAME: &str = wire::SERVICE_NAME;

/// The interface id every `devd` parcel carries.
pub const INTERFACE: u64 = wire::INTERFACE_ID;

/// A parcel of `method` carrying an already-encoded `body` (request or reply).
pub fn parcel(method: u32, body: Vec<u8>) -> Parcel {
    Parcel {
        header: Header {
            version: VERSION,
            flags: 0,
            interface_id: INTERFACE,
            method,
            txn_id: 0,
            reply_to: 0,
            deadline_ns: 0,
        },
        body,
        ..Parcel::default()
    }
}

/// A blocking client of `devd`: `Client::try_connect(Native)`.
pub type Client = wire::Client<Native>;
